/* ============ STATE (in-memory, no localStorage) ============ */
let cart = [];
let favorites = new Set();
let activeFilter = 'all';

/* ============ RENDER PRODUCTS ============ */
function fmt(n){ return 'Q' + n.toLocaleString('es-GT', {minimumFractionDigits:2}); }

function renderProducts(){
  const grid = document.getElementById('prodGrid');
  grid.innerHTML = '';
  let list = PRODUCTS.filter(p => {
    if(activeFilter==='all') return true;
    if(activeFilter==='under700') return p.price < 700;
    if(activeFilter==='700to1000') return p.price >= 700 && p.price <= 1000;
    if(activeFilter==='over1000') return p.price > 1000;
    return p.family.includes(activeFilter);
  });
  list.forEach((p,i) => {
    const card = document.createElement('div');
    card.className = 'prod-card';
    card.innerHTML = `
      <div class="prod-media">
        <div class="prod-badges">
          ${p.tag ? `<span class="badge ${p.tag==='Oferta'?'sale':''}">${p.tag}</span>` : ''}
        </div>
        <div class="prod-fav ${favorites.has(p.id)?'active':''}" onclick="toggleFav('${p.id}', this)">♡</div>
        <img src="${p.img}" alt="${p.brand} ${p.name}" loading="lazy">
        <div class="prod-quick" onclick="quickView('${p.id}')">Vista rápida</div>
      </div>
      <div class="prod-info">
        <span class="prod-brand">${p.brand}</span>
        <h3 class="prod-name">${p.name}</h3>
        <span class="prod-meta">${p.size} · ${p.gender}</span>
        <div class="prod-price-row"><span class="prod-price">${fmt(p.price)}</span></div>
        <span class="prod-avail">${p.stock ? 'Disponible' : 'Agotado'}</span>
        <button class="prod-add" onclick="addToCart('${p.id}')">Agregar al carrito</button>
      </div>`;
    grid.appendChild(card);
    setTimeout(()=>card.classList.add('show'), i*40);
  });
}

document.getElementById('filterBar').addEventListener('click', e=>{
  if(e.target.classList.contains('chip')){
    document.querySelectorAll('.chip').forEach(c=>c.classList.remove('active'));
    e.target.classList.add('active');
    activeFilter = e.target.dataset.filter;
    renderProducts();
  }
});
function filterByFamily(fam){
  activeFilter = fam;
  document.querySelectorAll('.chip').forEach(c=>c.classList.toggle('active', c.dataset.filter===fam));
  renderProducts();
  document.getElementById('perfumes').scrollIntoView({behavior:'smooth'});
}

function quickView(id){
  const p = PRODUCTS.find(x=>x.id===id);
  showToast(`${p.brand} ${p.name} — ${fmt(p.price)}`);
}

/* ============ FAVORITES ============ */
function toggleFav(id, el){
  if(favorites.has(id)){ favorites.delete(id); el.classList.remove('active'); }
  else { favorites.add(id); el.classList.add('active'); }
  const favCount = document.getElementById('favCount');
  favCount.textContent = favorites.size;
  favCount.style.display = favorites.size ? 'flex' : 'none';
}
function toggleFavPanel(){
  if(favorites.size===0){ showToast('Aún no tienes favoritos guardados.'); return; }
  const names = [...favorites].map(id=>PRODUCTS.find(p=>p.id===id).name).join(', ');
  showToast('Favoritos: ' + names);
}

/* ============ CART ============ */
function addToCart(id){
  const existing = cart.find(l=>l.id===id);
  if(existing){ existing.qty++; }
  else { cart.push({id, qty:1}); }
  renderCart();
  showToast('Producto agregado al carrito.');
  openCart();
}
function changeQty(id, delta){
  const line = cart.find(l=>l.id===id);
  if(!line) return;
  line.qty += delta;
  if(line.qty <= 0){ cart = cart.filter(l=>l.id!==id); }
  renderCart();
}
function removeLine(id){
  cart = cart.filter(l=>l.id!==id);
  renderCart();
}
function renderCart(){
  const itemsEl = document.getElementById('cartItems');
  const cartCount = document.getElementById('cartCount');
  const totalQty = cart.reduce((s,l)=>s+l.qty,0);
  cartCount.textContent = totalQty;
  cartCount.style.display = totalQty ? 'flex' : 'none';

  if(cart.length===0){
    itemsEl.innerHTML = '<div class="cart-empty">Tu carrito está vacío.</div>';
  } else {
    itemsEl.innerHTML = cart.map(l=>{
      const p = PRODUCTS.find(x=>x.id===l.id);
      return `<div class="cart-line">
        <img src="${p.img}" alt="${p.name}">
        <div class="cart-line-info">
          <h4>${p.brand} — ${p.name}</h4>
          <span>${p.size}</span>
          <div class="cart-line-qty">
            <button onclick="changeQty('${p.id}',-1)">−</button>
            <span>${l.qty}</span>
            <button onclick="changeQty('${p.id}',1)">+</button>
          </div>
          <div class="cart-line-price">${fmt(p.price*l.qty)}</div>
          <span class="cart-line-remove" onclick="removeLine('${p.id}')">Eliminar</span>
        </div>
      </div>`;
    }).join('');
  }
  const subtotal = cart.reduce((s,l)=>{
    const p = PRODUCTS.find(x=>x.id===l.id);
    return s + p.price*l.qty;
  },0);
  document.getElementById('cartSubtotal').textContent = fmt(subtotal);
}

function openCart(){
  document.getElementById('cartDrawer').classList.add('open');
  document.getElementById('overlay').classList.add('open');
}
function closeAllPanels(){
  document.getElementById('cartDrawer').classList.remove('open');
  document.getElementById('overlay').classList.remove('open');
}

/* ============ WHATSAPP ============ */
function buyNowWA(productName){
  let msg = 'Hola Frangacia Dlow, quisiera más información.';
  if(productName){
    msg = `Hola Frangacia Dlow, me interesa: ${productName}.`;
  } else if(cart.length){
    const lines = cart.map(l=>{
      const p = PRODUCTS.find(x=>x.id===l.id);
      return `- ${p.brand} ${p.name} (${l.qty})`;
    }).join('%0A');
    msg = `Hola Frangacia Dlow, quisiera hacer un pedido:%0A${lines}%0A%0ATotal aprox: ${document.getElementById('cartSubtotal').textContent}`;
  }
  window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(msg).replace(/%25/g,'%')}`, '_blank');
}

/* ============ NEWS ============ */
function renderNews(){
  document.getElementById('newsGrid').innerHTML = NEWS.map(n=>`
    <div class="news-card">
      <div class="news-media"><img src="${n.img}" alt="${n.title}"></div>
      <div class="news-body">
        <span class="news-cat">${n.cat}</span><span class="news-date">${n.date}</span>
        <h4 class="news-title">${n.title}</h4>
        <p class="news-excerpt">${n.excerpt}</p>
        <span class="news-link" onclick="showToast('Artículo completo próximamente.')">Leer más</span>
      </div>
    </div>`).join('');
}

/* ============ FAQ ============ */
function renderFaq(){
  document.getElementById('faqList').innerHTML = FAQS.map((f,i)=>`
    <div class="faq-item">
      <button class="faq-q" onclick="toggleFaq(${i})">${f.q}<span class="plus">+</span></button>
      <div class="faq-a" id="faqA${i}"><p>${f.a}</p></div>
    </div>`).join('');
}
function toggleFaq(i){
  const item = document.querySelectorAll('.faq-item')[i];
  const a = document.getElementById('faqA'+i);
  const isOpen = item.classList.contains('open');
  document.querySelectorAll('.faq-item').forEach((el,idx)=>{
    el.classList.remove('open');
    document.getElementById('faqA'+idx).style.maxHeight = null;
  });
  if(!isOpen){ item.classList.add('open'); a.style.maxHeight = a.scrollHeight+'px'; }
}

/* ============ TOAST ============ */
let toastTimer;
function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(()=>t.classList.remove('show'), 3200);
}

/* ============ MOBILE MENU ============ */
function toggleMobileMenu(){
  document.getElementById('mobileMenu').classList.toggle('open');
}

/* ============ SCROLL REVEAL ============ */
const io = new IntersectionObserver((entries)=>{
  entries.forEach(e=>{ if(e.isIntersecting) e.target.classList.add('in'); });
},{threshold:0.12});
document.querySelectorAll('.reveal').forEach(el=>io.observe(el));

/* ============ INIT ============ */
renderProducts();
renderCart();
renderNews();
renderFaq();
